const updateActivity = `-- name: UpdateActivity :execrows
UPDATE activities SET
  title = COALESCE($1::text, title),
  description = COALESCE($2::text, description),
  venue = COALESCE($3::text, venue),
  starts_at = COALESCE($4::timestamptz, starts_at),
  ends_at = COALESCE($5::timestamptz, ends_at),
  unit_id = CASE WHEN $6::boolean THEN NULL
                 ELSE COALESCE($7::uuid, unit_id) END,
  quorum_percent = COALESCE($8::int, quorum_percent),
  capacity = COALESCE($9::int, capacity),
  status = COALESCE($10::text, status),
  -- a reschedule re-arms the reminder: a moved meeting gets a fresh notice.
  reminder_sent = reminder_sent AND $4 IS NULL
WHERE id = $11::uuid AND organization_id = $12::uuid
  AND status <> 'cancelled'
`

type UpdateActivityParams struct {
	Title          pgtype.Text        `json:"title"`
	Description    pgtype.Text        `json:"description"`
	Venue          pgtype.Text        `json:"venue"`
	StartsAt       pgtype.Timestamptz `json:"starts_at"`
	EndsAt         pgtype.Timestamptz `json:"ends_at"`
	ClearUnit      bool               `json:"clear_unit"`
	UnitID         pgtype.UUID        `json:"unit_id"`
	QuorumPercent  pgtype.Int4        `json:"quorum_percent"`
	Capacity       pgtype.Int4        `json:"capacity"`
	Status         pgtype.Text        `json:"status"`
	ID             pgtype.UUID        `json:"id"`
	OrganizationID pgtype.UUID        `json:"organization_id"`
}

func (q *Queries) UpdateActivity(ctx context.Context, arg UpdateActivityParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateActivity,
		arg.Title,
		arg.Description,
		arg.Venue,
		arg.StartsAt,
		arg.EndsAt,
		arg.ClearUnit,
		arg.UnitID,
		arg.QuorumPercent,
		arg.Capacity,
		arg.Status,
		arg.ID,
		arg.OrganizationID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

